SELECT relation.skill_id AS skillId, COUNT(DISTINCT relation.agent_id) AS boundAgentCount
FROM agent_skill relation
    INNER JOIN agent ON agent.id = relation.agent_id AND agent.deleted = 0
WHERE relation.enabled = 1 AND relation.skill_id IN

   #{skillId}

GROUP BY relation.skill_id;

SELECT relation.skill_id AS skillId, COUNT(DISTINCT relation.agent_id) AS boundAgentCount FROM agent_skill relation INNER JOIN agent ON agent.id = relation.agent_id AND agent.deleted = 0 AND agent.space_id = #{spaceId} WHERE relation.enabled = 1 AND relation.skill_id IN
#{skillId}
GROUP BY relation.skill_id

SELECT skill.id, skill.scope_type, CASE WHEN skill.scope_type = 'SYSTEM' THEN #{spaceId} ELSE skill.space_id END AS space_id, skill.name, skill.display_name, skill.description, CASE WHEN skill.scope_type = 'SYSTEM' THEN installation.enabled ELSE skill.status END AS status, skill.next_version_no, skill.created_by, skill.created_at, CASE WHEN skill.scope_type = 'SYSTEM' THEN installation.updated_at ELSE skill.updated_at END AS updated_at, skill.deleted, installation.id AS installation_id, installation.skill_version_id AS installed_version_id FROM skill LEFT JOIN space_skill_installation installation ON installation.skill_id = skill.id AND installation.space_id = #{spaceId} WHERE skill.deleted = 0 AND ((skill.scope_type = 'SPACE' AND skill.space_id = #{spaceId}) OR (skill.scope_type = 'SYSTEM' AND skill.space_id IS NULL AND installation.id IS NOT NULL))
AND CASE WHEN skill.scope_type = 'SYSTEM' THEN installation.enabled ELSE skill.status END = #{status}
AND skill.scope_type = #{sourceType}
AND (skill.name LIKE CONCAT('%', #{keyword}, '%') OR skill.display_name LIKE CONCAT('%', #{keyword}, '%') OR skill.description LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY CASE WHEN skill.scope_type = 'SYSTEM' THEN installation.updated_at ELSE skill.updated_at END DESC, skill.id DESC
